import Foundation

enum F1LegacyHeader {
    // Exact 4 KiB header used by the hardware-verified candidate 3 export.
    private static let encoded = ""

    static let data: Data = {
        guard let data = Data(base64Encoded: encoded), data.count == 4096 else {
            preconditionFailure("The bundled F1 header is invalid.")
        }
        return data
    }()
}
